    def __init__(self, graph):
        self.graph = graph
        self.visited = set()
        self.path = []

    def cycle_based_search(self, start_node):
        stack = [start_node]
        while stack:
            node = stack[-1]
            if node not in self.visited:
                self.visited.add(node)
                if node in self.graph:
                    stack.extend(self.graph[node])
                else:
